// LoadCorrection loads the correctionEvidenceLink's Correction into the .R struct
func (o *CorrectionEvidenceLink) LoadCorrection(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Correction = nil
	o.R.Loaded.Correction = false

	related, err := o.Correction(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.CorrectionEvidenceLinks = CorrectionEvidenceLinkSlice{o}

	o.R.Correction = related
	o.R.Loaded.Correction = true
	return nil
}

// LoadCorrection loads the correctionEvidenceLink's Correction into the .R struct
func (os CorrectionEvidenceLinkSlice) LoadCorrection(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	corrections, err := os.Correction(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Correction = nil
		o.R.Loaded.Correction = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range corrections {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.CorrectionID == rel.ID) {
				continue
			}

			rel.R.CorrectionEvidenceLinks = append(rel.R.CorrectionEvidenceLinks, o)

			o.R.Correction = rel
			break
		}
	}

	return nil
}

